const spark=(n=0)=>`<svg viewBox="0 0 80 25" aria-hidden="true"><path d="M1 ${20-n} L12 17 L22 20 L32 9 L42 12 L52 6 L64 9 L78 2" stroke="#a58451" fill="none" stroke-width="1.5"/></svg>`;
