const ava=(n)=>`<span class="avatar" title="${n}">${n.split(' ').map(x=>x[0]).join('')}</span>`;
const appAction=()=>[btn('Open sample RFP',"state.proposal=true;state.chat.push(['ai','I’ve loaded the sample Operations Modernization RFP. It includes 12 requirements, a 90-day window, and a $75,000 ceiling. Which outcome should we emphasize?']);tab=0;render()",'primary'),btn('Generate sequences ','state.response=true;tab=1;render()','primary'),btn('Correlate signals ',"draw('Signals connected','<div class=callout>Northstar’s webinar attendance, website inquiry, and referral are linked to a single account. The lead score is 94/100.</div>'+btn('Review matched account','state.lead=0;closeDrawer();tab=0;render()','primary'))",'primary'),btn('Run focus group ','runPanel()','primary'),btn('Export plan ↓',"download('Nine-67-budget.csv','Department,Annual budget\\n'+['Operations','Marketing','Technology','People'].map((x,i)=>x+','+state.budget[i]).join('\\n'))",'primary'),btn('Explore forecast ↗','nav(9)','primary'),btn(state.rebalance?'Undo rebalance':'AI rebalance ',`state.rebalance=${!state.rebalance};render()`,'primary'),btn('Add update +',"draw('Project update','<label class=field>Share an update<textarea id=newpost></textarea></label>'+btn('Post to project',\"state.posts.push(document.getElementById('newpost').value);closeDrawer();render()\",'primary'))",'primary'),btn('Ask your reports ','askReports()','primary'),btn('Save scenario','saveScenario()','primary'),btn('Export business case ↓','exportRoi2()','primary'),btn('Portfolio briefing ','portfolioBrief()','primary'),btn(state.night?'Research complete ✓':'Run research ',"state.night=true;toast('Sample research completed. Four companies ready to explore.');render()",'primary')][current];
render=function(){document.body.dataset.app=current;$('#sidebar').innerHTML=`<div class="brand"><span class="moon"></span>Nine-67</div><div class="navlabel">WORKSPACE</div>${btn('<span class="ico"></span> Application library','nav(-1)','nav '+(current<0?'active':''))}<div class="navlabel">YOUR APPLICATIONS &nbsp; <span style="opacity:.6">13</span></div>${toolsList.map((x,i)=>btn(`<span class="ico">${x[1]}</span>${x[0]}`,`nav(${i})`,'nav '+(current===i?'active':''))).join('')}<div class="sidefoot"><div class="row"><b>Nine-67 workspace</b><span class="dot"></span></div>Client demonstration environment<br>${btn('Explore integrations ↗','openArchitecture()','link')}</div>`;$('#crumb').innerHTML=`<span style="color:#655545">Applications</span> &nbsp; / &nbsp; <b style="color:var(--ink);font-weight:500">${current<0?'Library':toolsList[current][0]}</b>`;if(current<0){$('#main').innerHTML=library2();return}let html=`<div class="appbar"><div class="appname"><div class="appmark">${toolsList[current][1]}</div><div><h1>${toolsList[current][0]}</h1><small>${['Your next proposal starts with a conversation.','Webinar intelligence → meaningful conversations','Every signal connected. Every lead in context.','Simulation persona / focus group','Collaborative planning, powered by conversation','Revenue intelligence for leadership','The right people, on the right work','Operations modernization / Project workspace','Your organization, in focus','Turn assumptions into a clearer outlook','Understand the value before you build','Every initiative. One shared view.','Company intelligence & outreach'][current]}</small></div></div><div class="appactions"><div class="avatars">${ava('Alex Morgan')}${ava('Taylor Kim')}${ava('Jordan Ellis')}</div>${appAction()}</div></div><nav class="appnav">${subnavs[current].map((x,i)=>btn(x,`tab=${i};render()`,tab===i?'active':'')).join('')}<span class="right"><span class="dot"></span> Sample workspace · Changes stay in this session</span></nav>`;const custom=[proposal2,response2,triage2,simulation2,budget2,sales2,resources2,collaboration2,insights2,forecast2,roi2,tracker2,nightwatch2];html+=custom[current]();$('#main').innerHTML=html;};
function legacy(i){return `<div class="appbody">${originalViews[i]()}</div>`}
function miniPreview(i){return `<div class="tilePreview"><div class="tileWindow"><div class="tileLines">${Array.from({length:7},(_,j)=>`<i style="width:${60+j%3*15}%;${j===i%5?'background:#bf9b67':''}"></i>`).join('')}</div><div class="tileContent"><div class="tinybar"></div>${[0,3,7].includes(i)?`<div style="background:#f5f1e9;padding:7px;border-radius:4px;margin:7px 0"><div style="height:3px;background:#ddd2be;width:75%;margin-bottom:5px"></div><div style="height:3px;background:#e6dfd3;width:92%"></div></div><div style="background:#ece1cd;height:17px;width:60%;margin-left:auto;border-radius:4px"></div><div style="border:1px solid #e4ddce;height:20px;border-radius:4px;margin-top:9px"></div>`:[4,6,11].includes(i)?`<div class="tinycards"><div></div><div></div><div></div></div>${Array.from({length:3},(_,j)=>`<div style="border-bottom:1px solid #eee9df;height:15px;padding:4px 0"><div style="height:6px;background:${j===1?'#c7d2bf':'#dfcfb4'};width:${35+j*20}%;margin-left:${j*10}%;border-radius:2px"></div></div>`).join('')}`:`<div class="tinycards"><div></div><div></div><div></div></div><svg viewBox="0 0 160 45" style="width:100%;height:45px"><path d="M0 40L20 32L40 35L60 19L80 26L100 13L120 20L140 6L160 2V45H0Z" fill="#f1e6d2"/><path d="M0 40L20 32L40 35L60 19L80 26L100 13L120 20L140 6L160 2" fill="none" stroke="#b18b50" stroke-width="2"/></svg>`}</div></div></div>`}
function library2(){return `<div class="suitehome"><div class="suiteintro"><div><div class="eyebrow">YOUR NINE-67 APPLICATIONS</div><h1>A workspace for every possibility.</h1><p>Step inside the tools. Explore the workflows. See what your team could do.</p></div>${btn('Explore Proposal Builder →','nav(0)','primary')}</div><div class="featuredapp"><div class="featuredcopy"><div class="eyebrow">FEATURED WORKSPACE / NIGHTWATCH</div><h1>Your next opportunity.<br>Already researched.</h1><p>From a market signal to a relevant conversation. Explore company intelligence and three approaches to outreach.</p>${btn('Open Nightwatch ↗','nav(12)','gold')}</div><div class="featuredpreview"><div class="previewwindow"><div class="previewtop"> &nbsp; Nightwatch <span style="float:right;color:#655545">Company intelligence</span></div><div class="previewinside"><div class="previewside"><b>Morning briefing</b><br>Company lists<br>Research signals<br>Outreach drafts<br>Results</div><div class="previewbody"><h3 style="font-size:13px">A more informed start to your day.</h3><div class="miniappstats"><div>Companies researched<b>50</b></div><div>Qualified matches<b>24</b></div><div>Outreach versions<b>72</b></div></div><div style="margin-top:17px;background:white;border:1px solid var(--line);border-radius:5px;padding:13px;font-size:10px"><b>Northstar Manufacturing</b><span style="float:right;color:#488068">94 fit</span><p style="color:var(--muted);font-size:9px">New facility · Operations efficiency · Pennsylvania</p><div class="bar"><i style="width:94%"></i></div></div></div></div></div></div></div><div class="sectionhead"><div><h2>Application library <span class="tag" style="margin-left:7px">13</span></h2><p>Purpose-built experiences across the way you work.</p></div><div class="suggestions">${['All','Growth','Delivery','Planning','Intelligence'].map(x=>btn(x,`state.filter='${x}';render()`,state.filter===x?'primary':'')).join('')}</div></div><div class="catalogue">${toolsList.map((x,i)=>state.filter==='All'||state.filter===x[2]?`<button class="appTile" onclick="nav(${i})">${miniPreview(i)}<div class="tileText"><span class="eyebrow" style="font-size:8px">${x[2]}</span><h2>${x[0]}</h2><p>${x[3]}</p><div class="row"><span>Open application</span><span>↗</span></div></div></button>`:'').join('')}</div></div>`}
function proposal2(){if(tab===2)return legacy(0);if(tab===1)return `<div class="editorgrid"><div class="editorrail"><div class="eyebrow" style="font-size:9px;margin:4px 8px 18px">PROPOSAL OUTLINE</div>${sections.map((x,i)=>btn(`<b>${i+1}. ${x}</b><small>${i===4?'2 items to review':i===state.section?'Currently editing':'Draft section'}</small>`,`state.section=${i};render()`,'railitem '+(i===state.section?'selected':''))).join('')}<div class="callout" style="margin-top:25px">10 of 12 requirements covered${bar(83)}</div></div><div class="editorpane"><div class="sectionhead"><h2>${sections[state.section]}</h2>${tag('Draft','amber')}</div><div class="toolbar"><b>B</b><i>I</i><u>U</u><span>│</span><span>H₂</span><span>≡</span><span></span><span>↗</span></div><textarea id="proposalText" oninput="state.drafts[state.section]=this.value;document.getElementById('previewText').textContent=this.value">${esc(state.drafts[state.section]||proposalText())}</textarea><div class="row">${btn('Refine with AI ','refineProposal()')}${btn('Export proposal ↓','exportProposal()','primary')}</div></div><div class="paperpane"><div class="sectionhead"><span class="subtle">LIVE DOCUMENT PREVIEW</span>${tag('A4 · Portrait')}</div><article class="paper"><div class="row"><b>Nine-67</b><span class="subtle">OPERATIONS MODERNIZATION</span></div><div class="rule"></div><h2>${sections[state.section]}</h2><div id="previewText" style="white-space:pre-wrap">${esc(state.drafts[state.section]||proposalText())}</div><div class="paperfoot">NINE-67 &nbsp; / &nbsp; CONFIDENTIAL PROPOSAL &nbsp; / &nbsp; ${state.section+1}</div></article></div></div>`;return `<div class="workspace"><div class="rail"><h3>Recent proposals</h3>${btn('<b>Operations modernization</b><small>Active conversation · Just now</small>','state.proposal=true;render()','railitem selected')}${btn('<b>Customer intelligence pilot</b><small>Example brief · Draft</small>',"draw('Customer intelligence pilot','<p>Sample brief: unify customer feedback, identify recurring themes, and surface next actions for account teams.</p>'+btn('Start from this brief',\"closeDrawer();proposalChat('Build a customer intelligence pilot')\",'primary'))",'railitem')}${btn('<b>Quarterly planning platform</b><small>Example brief · In review</small>',"draw('Quarterly planning platform','<p>Sample brief: connect financial planning inputs, compare scenarios, and prepare a leadership review.</p>'+btn('Start from this brief',\"closeDrawer();proposalChat('Build a quarterly planning platform')\",'primary'))",'railitem')}<h3 style="margin-top:30px">Knowledge & sources</h3>${btn(' &nbsp; Company capabilities','draw("Company capabilities","<p>Nine-67 builds practical AI tools around business workflows, integrating the systems and data your team uses.</p>")','railitem')}${btn(' &nbsp; Proposal templates','tab=1;render()','railitem')}<div class="callout" style="margin-top:30px"><b>Built with your context.</b><br>Your conversation, RFP, and supporting sources shape the response.</div></div><div class="appbody" style="width:100%"><div class="stagebar">${['Understand','Structure','Draft','Review'].map((x,i)=>`<div class="stagepill ${i===0?'active':''}"><span>${i+1}</span>${x}</div>`).join('')}</div><div class="detailgrid"><section class="surface chatcanvas"><div class="chatwelcome"><div class="aiorb"></div><div class="eyebrow" style="font-size:9px">YOUR PROPOSAL PARTNER</div><h1>What are we building<br>a proposal for?</h1><p>Tell me about the opportunity, or drop in the RFP.<br>We’ll work through the response together.</p></div>${state.chat.length?`<div class="chat" style="min-height:0;margin-bottom:20px">${state.chat.map(([r,s])=>`<div class="bubble ${r==='user'?'user':''}">${esc(s)}</div>`).join('')}</div>`:`<div class="promptgrid">${btn('Start from an RFP <span>Upload the brief and identify requirements</span>',"document.getElementById('rfpfile').click()",'promptcard')}${btn('Shape a 90-day pilot <span>Define a practical scope and success measures</span>',"proposalChat('Help me shape a 90-day pilot')",'promptcard')}${btn('Improve an existing proposal <span>Make the response clearer and more specific</span>','tab=1;render()','promptcard')}${btn('Find the missing pieces <span>Check requirements and supporting evidence</span>','tab=2;render()','promptcard')}</div>`}<div class="inputbox"><textarea id="proposalInput" placeholder="Tell me about the opportunity, or ask a question…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();proposalChat()}"></textarea><div class="row"><div>${btn('＋ Attach RFP',"document.getElementById('rfpfile').click()")}${btn('Use sample RFP',"state.proposal=true;proposalChat('Use the sample Operations Modernization RFP')")}</div>${btn('Send ↑','proposalChat()','primary')}</div><input hidden type="file" id="rfpfile" accept=".pdf,.docx,.txt" onchange="proposalUpload(this)"></div><p class="subtle" style="text-align:center">Simulated AI conversation · Files remain local in this prototype</p></section><div class="stack" style="align-content:start">${surface('Working brief',`<span class="eyebrow" style="font-size:9px">OPPORTUNITY</span><h2 style="font-size:20px;line-height:1.3;margin:12px 0">Operations<br>Modernization</h2>${tag(state.proposal?'RFP added':'Sample opportunity',state.proposal?'green':'')}<div class="listitem row"><span class="muted">Timeline</span><b>90 days</b></div><div class="listitem row"><span class="muted">Budget ceiling</span><b>$75,000</b></div><div class="listitem row"><span class="muted">Requirements</span><b>12 identified</b></div><div class="listitem row"><span class="muted">Sections</span><b>5 planned</b></div>${btn('Open working draft →','tab=1;render()','link')}`)}${surface('Source materials',`<div class="filechip"><span class="fileicon"></span><div><b>Sample_RFP.pdf</b><small>Illustrative · 12 requirements</small></div></div><div class="filechip"><span class="fileicon"></span><div><b>Capabilities brief</b><small>Nine-67 · Reference material</small></div></div><div class="callout"><b>Next question</b><br>What outcome matters most to the selection team?</div>`)}</div></div></div></div>`}
function response2(){if(tab===2)return legacy(1);if(tab===1)return emailStudio();return `<div class="workspace"><div class="rail"><h3>Webinar campaigns</h3>${btn('<b>AI in Everyday Operations</b><small>Oct 15 · 148 registered</small>','render()','railitem selected')}${btn('<b>Smarter Financial Planning</b><small>Example campaign · Sep 24</small>',"draw('Smarter Financial Planning','<p>Archived sample campaign: 96 attendees, 3 audience segments, and a four-email sequence.</p>')",'railitem')}<h3 style="margin-top:28px">Audience segments</h3>${['All registrants · 148','Operations leaders · 64','Finance leaders · 46','Growth leaders · 38'].map((s,i)=>btn(s,`audienceSegment(${i})`,'railitem')).join('')}<div class="callout" style="margin-top:25px"><b>Relevant follow-ups.</b><br>Use what each person watched, asked, and downloaded.</div></div><div class="appbody" style="width:100%"><div class="minihero"><div><div class="eyebrow" style="font-size:9px">WEBINAR CAMPAIGN / OCTOBER 15, 2026</div><h2>AI in Everyday Operations</h2><p>From a great session to the right next conversation.</p></div><span class="badge">${state.response?'Sequences generated ✓':'Ready to personalize '}</span></div>${slim([['Registrations','148','4 audience signals'],['Attendance','112','76% attendance rate'],['High engagement','38','Watched over 75%'],['Drafts ready',state.response?'148':'0','Review before delivery']])}<div class="campaigngrid"><div>${surface('Webinar intelligence',`<div class="video"><div class="eyebrow" style="color:#655545;font-size:8px">NINE-67 / WEBINAR</div><h2>Less chasing.<br>More getting things done.</h2>${btn(' View transcript',"draw('Webinar transcript','<span class=tag>Sample transcript · 48 minutes</span><div class=listitem><b>03:24 — Start with one workflow</b><p>Choose a repeated handoff that consumes time every week. Establish a baseline before automating.</p></div><div class=listitem><b>18:10 — Shared project visibility</b><p>A common view of owners, exceptions, and next steps helps teams move faster.</p></div><div class=listitem><b>36:45 — Audience question</b><p>How quickly can a team see a first working iteration? Start with a focused two-week milestone.</p></div>')")}<span style="float:right;font-size:10px;color:#655545">48:12</span></div><div class="waveform">${Array.from({length:72},(_,i)=>`<i style="height:${8+(i*17%28)}px"></i>`).join('')}</div><div class="row"><span class="subtle">RECOGNIZED THEMES</span>${tag('Transcript analyzed','green')}</div><div class="suggestions">${['Operational handoffs','Reporting efficiency','First AI pilot'].map(x=>tag(x)).join(' ')}</div><p class="muted" style="font-size:11px">The session focused on choosing a measurable first workflow, connecting existing systems, and building team adoption.</p>`)}<div class="sectionhead" style="margin-top:24px"><h2>The conversation continues</h2>${btn('Edit sequence →','state.response=true;tab=1;render()','link')}</div><div class="timelineflow">${['Webinar recap','Useful next step','Practical example','Let’s talk'].map((x,i)=>`<div class="sequencecard ${i===0?'active':''}"><small>${['DAY 0','DAY 3','DAY 7','DAY 14'][i]}</small><h3>${x}</h3>${tag(i===0?'Initial email':'Follow-up '+i)}${btn('Preview ↗',`state.emailDay=${i};tab=1;render()`)}</div>`).join('')}</div></div><div class="stack" style="align-content:start">${surface('Audience engagement',`${[['Registered',148,100],['Attended',112,76],['Engaged',68,46],['High intent',38,26]].map(([x,n,p])=>`<div class="funnelrow"><span>${x}</span>${bar(p)}<b>${n}</b></div>`).join('')}<div class="callout"><b>38 high-engagement attendees</b><br>Prioritize relevant content around their questions.</div>`)}${surface('Campaign checklist',`${['Transcript context ready','Recording reference added','Supporting guide selected','Personalized sequences reviewed'].map((x,i)=>`<div class="listitem row" style="padding:12px 0"><span style="font-size:10px">${x}</span><span style="color:${i<3?'var(--green)':'var(--gold)'}">${i<3?'✓':'○'}</span></div>`).join('')}<label class="field" style="margin-top:15px">Add supporting material<input type="file" onchange="toast('Supporting file selected locally')"></label>`)}</div></div>${surface('People behind the numbers',table(['Attendee','Organization','Engagement','Score',''],people.map((p,i)=>[`<div class="person">${ava(p[0])}<div><b>${p[0]}</b><small>${p[1]}</small></div></div>`,p[2],p[4],tag(p[3],'green'),btn('Open sequence ↗',`state.selectedPerson=${i};tab=1;render()`)])))}</div></div>`}
function audienceSegment(i){draw(['All registrants','Operations leaders','Finance leaders','Growth leaders'][i],`<p>Sample audience segment · ${[148,64,46,38][i]} recipients</p>${table(['Contact','Role','Score'],people.slice(i===2?1:0,i===2?3:3).map(p=>[p[0],p[1],tag(p[3],'green')]))}${btn('Review personalized sequence','closeDrawer();tab=1;render()','primary')}`)}
function emailStudio(){let p=people[state.selectedPerson];return `<div class="workspace"><div class="rail"><h3>Recipients</h3>${people.map((p,i)=>btn(`<b>${p[0]}</b><small>${p[2]}</small>`,`state.selectedPerson=${i};render()`,'railitem '+(i===state.selectedPerson?'selected':''))).join('')}<div class="callout" style="margin-top:25px">Personalization uses role, watch time, questions, and content engagement.</div></div><div class="appbody" style="width:100%"><div class="sectionhead"><div><h2>${p[0]} <span class="tag green">Score ${p[3]}</span></h2><p>${p[1]} · ${p[2]}</p></div>${tag('Ready for review','amber')}</div><div class="timelineflow">${['Webinar recap','Useful next step','Practical example','Conversation'].map((s,i)=>`<div class="sequencecard ${state.emailDay===i?'active':''}" onclick="state.emailDay=${i};render()" style="cursor:pointer"><small>DAY ${[0,3,7,14][i]}</small><h3>${s}</h3>${tag(i===0?'Initial email':'Follow-up '+i)}</div>`).join('')}</div><div class="detailgrid">${surface('Email editor',`<div class="row"><span class="subtle">FROM: THE NINE-67 TEAM</span>${tag('Draft')}</div>${field('Subject','mailSubject',['Your next step after our operations webinar','A simple handoff map for your team','What a first working iteration could look like','Would a workflow conversation help?'][state.emailDay])}<textarea id="mailText" style="min-height:320px;border:0;padding:15px 0" oninput="state.drafts['mail'+state.selectedPerson+state.emailDay]=this.value">${esc(state.drafts['mail'+state.selectedPerson+state.emailDay]||`Hi ${p[0].split(' ')[0]},\n\n${['Thanks for your interest in the operations webinar. The discussion about reducing manual reporting seemed particularly relevant to your work at '+p[2]+'.','One useful place to start is mapping a single reporting handoff. Who prepares the information, who checks it, and where does it go next?','A focused two-week first iteration could give your team a shared view of outstanding requests and their owners. The pilot would help validate whether it reduces follow-up time.','I wanted to check whether improving your reporting workflow is a priority this quarter. If it is, would a short conversation about where to start be useful?'][state.emailDay]}\n\n${state.emailDay<3?'I’ve included a practical guide to help your team choose a measurable first step.':''}\n\nBest,\nThe Nine-67 team`)}</textarea><div class="row">${btn('Save draft',"toast('Draft retained for this session')")}${btn('Approve sequence ✓','state.approved=true;tab=2;render()','primary')}</div>`)}<div class="stack" style="align-content:start">${surface('Why this message',`<div class="listitem"><b>Role relevance</b><p>${p[1]} at ${p[2]}</p></div><div class="listitem"><b>Engagement context</b><p>${p[4]}</p></div><div class="listitem"><b>Content selected</b><p>Your first AI operations pilot · Guide</p></div><div class="callout">No emails are sent from this demonstration.</div>`)}${surface('Follow-up timing',`${[3,7,14].map((n,i)=>`<label class="field">Follow-up ${i+1} · days after initial email<input type="number" min="1" value="${state['day'+i]||n}" onchange="state['day'+${i}]=+this.value"></label>`).join('')}<p class="subtle">A reply stops the remaining sequence.</p>`)}</div></div></div></div>`}
function triage2(){if(tab>0)return legacy(2);let p=people[state.lead];return `<div class="triagegrid"><div class="inboxlist"><div class="sectionhead"><h2>Priority inbox</h2>${tag('12 new','amber')}</div><input id="leadSearch" placeholder="Search leads…" oninput="filterLeads(this.value)" style="font-size:11px;margin-bottom:14px">${people.map((x,i)=>`<button class="leadrow ${i===state.lead?'selected':''}" data-lead="${x[0].toLowerCase()} ${x[2].toLowerCase()}" onclick="state.lead=${i};render()"><div class="row"><h3>${x[0]}</h3>${tag(x[3],'green')}</div><p>${x[2]}</p><div class="row"><span>${['3 signals connected','2 signals connected','1 signal connected','New registration'][i]}</span><span>${['12m','38m','1h','2h'][i]}</span></div></button>`).join('')}<div class="callout" style="margin-top:20px"><b>Account matching active</b><br>Contacts, engagement, and inquiries are correlated into one account view.</div></div><div class="leadpane"><div class="row"><div class="profilelogo">${p[2].split(' ').map(x=>x[0]).join('')}</div>${tag('High intent','green')}</div><h1>${p[2]}</h1><p class="muted" style="font-size:11px">${p[0]} · ${p[1]}</p><div class="suggestions">${tag('Mid-market')}${tag('United States')}${tag('Operations efficiency')}</div><div class="callout" style="margin:22px 0"><b> Account intelligence</b><br>${p[0].split(' ')[0]} is engaging with content on reporting and handoffs. The combination of role relevance and recent interest suggests a timely discovery conversation.</div><div class="sectionhead"><h2>The complete signal story</h2><span class="subtle">LAST 7 DAYS</span></div><div class="signalpath">${[['Today · 9:42 AM','Website inquiry received','Asked about connecting reporting across multiple systems.'],['Yesterday · 2:18 PM','Downloaded the first-pilot guide','Viewed content on workflow selection and baseline measurement.'],['Oct 15 · 11:00 AM','Attended operations webinar',p[4]],['Oct 12 · 4:22 PM','Account matched','Matched to the existing account using the company domain.']].map(([a,b,c])=>`<div class="signal"><small>${a}</small><b>${b}</b><p>${c}</p></div>`).join('')}</div><div class="sectionhead"><h2>Related contacts</h2>${btn('Account profile ↗',`leadDetail(${state.lead})`,'link')}</div><div class="person">${ava('Jordan Miles')}<div><b style="font-size:11px">Jordan Miles</b><p class="muted" style="margin:5px 0;font-size:10px">IT Manager · Same account · Sample contact</p></div></div></div><div class="actionpane"><div class="eyebrow" style="font-size:9px">QUALIFICATION</div><div class="fitcircle">${p[3]}<small>ACCOUNT FIT</small></div>${[['Role alignment',96],['Business relevance',92],['Recent intent',p[3]]].map(([x,n])=>`<div class="metricline" style="font-size:10px"><span>${x}</span><b>${n}</b></div>${bar(n,true)}`).join('')}<h3 style="margin:28px 0 12px">Recommended next action</h3><div class="callout">Invite ${p[0].split(' ')[0]} to a discovery call focused on the reporting workflow.</div><label class="field" style="margin-top:22px">Assigned owner<select id="triageOwner"><option>Alex Morgan</option><option>Jordan Ellis</option><option>Taylor Kim</option></select></label>${btn('Accept & assign lead',"state.assignedLead=state.lead;toast('Lead assigned to '+document.getElementById('triageOwner').value);document.getElementById('assignStatus').textContent='Assigned · Discovery follow-up created'",'primary')}<p id="assignStatus" class="subtle">${state.assignedLead===state.lead?'Assigned · Discovery follow-up created':'Suggested response time: within 2 hours'}</p><div class="listitem"><b style="font-size:10px">Suggested discovery question</b><p>How much time does your team spend chasing reporting updates each week?</p></div></div></div>`}
