function resources2(){if(tab>0)return legacy(6);const names=['Alex Morgan','Jordan Ellis','Taylor Kim','Sam Rivera','Casey Lane'];let loads=state.rebalance?[90,85,95,80,88]:[120,65,105,70,78];return `<div class="appbody"><div class="sectionhead"><div><h2>Plan the week with confidence.</h2><p>October 19–23, 2026 · 12 people · 6 active projects</p></div><div class="suggestions">${tag('Week view')}${btn('Skills & availability',"draw('Team skills','<p>Alex: Solution design & dashboards<br>Jordan: Data modeling & analytics<br>Taylor: Application development<br>Sam: Quality assurance & testing<br>Casey: Delivery & adoption</p>')")}</div></div>${slim([['Team utilization',state.rebalance?'88%':'94%','Target: 80–95%'],['Over capacity',state.rebalance?'0 people':'2 people',state.rebalance?'Capacity balanced':'Action recommended'],['Available capacity',state.rebalance?'58 hrs':'32 hrs','This week'],['Delivery commitments','6 projects','All upcoming milestones']])}<div class="schedule"><div class="schedhead"><div style="text-align:left">TEAM MEMBER / CAPACITY</div>${['MON 19','TUE 20','WED 21','THU 22','FRI 23'].map(x=>`<div>${x}</div>`).join('')}</div>${names.map((n,i)=>`<div class="schedrow"><div><div class="schedperson">${ava(n)}<div><b>${n}</b><small>${['Solutions engineer','Data & analytics','Application engineer','Quality assurance','Delivery lead'][i]}</small></div></div><div class="row" style="font-size:9px;margin-top:8px"><span>${Math.round(loads[i]*.4)} / 40 hrs</span><span style="color:${loads[i]>100?'var(--red)':'var(--green)'}">${loads[i]}%</span></div></div>${Array.from({length:5},(_,j)=>`<div>${j===4&&i===4?'<div class="allocation" style="background:#eee;color:#61605d;border-style:dashed">Out of office · 4h</div>':`<div class="allocation ${loads[i]>100&&!state.rebalance?'red':i%2?'gold':''}" onclick="assignment(${i})">${['Reporting','Forecast model','Workspace','Testing','Pilot review'][i]} · ${state.rebalance?Math.round(loads[i]*.08):[10,5,9,6,6][i]}h</div>${j===1||j===3?`<div class="allocation gold" onclick="assignment(${i})">${state.rebalance&&i===1?'Reassigned work':'Project sync'} · 1h</div>`:''}`}</div>`).join('')}</div>`).join('')}</div><div class="two" style="margin-top:22px">${surface(' A more balanced plan',`<div class="row"><div><h3>${state.rebalance?'12 hours redistributed. Deadlines preserved.':'Two people need a little breathing room.'}</h3><p class="muted">${state.rebalance?'Alex and Taylor are now below their weekly capacity. Jordan and Sam have taken on work aligned with their skills.':'Move 8 hours of reporting work to Jordan and 4 hours of testing to Sam. Both have matching skills and availability.'}</p></div></div><div class="row">${tag(state.rebalance?'Recommendation applied':'Suggested adjustment',state.rebalance?'green':'amber')}${btn(state.rebalance?'Undo changes':'Apply rebalance',`state.rebalance=${!state.rebalance};render()`,'primary')}`)}${surface('Capacity over the next two weeks',`<div class="capacityheat">${Array.from({length:20},(_,i)=>`<div class="${i%7===0&&!state.rebalance?'high':i%3?'mid':''}" title="${i<10?'Week 1':'Week 2'} capacity"></div>`).join('')}</div><div class="legend" style="margin-top:18px"><span><i style="background:#e2e9dd"></i>Available</span><span><i style="background:#c3cdb7"></i>Balanced</span><span><i style="background:#ba8a61"></i>Over capacity</span></div><p class="subtle">Upcoming: Casey on leave Friday afternoon.</p>`)}</div></div>`}
function collaboration2(){if(tab>0)return legacy(7);return `<div class="appbody"><div class="projectbanner"><div><div class="eyebrow" style="font-size:9px">NINE-67 / SHARED PROJECT WORKSPACE</div><h1>Operations modernization</h1><p>One team. One place to move the work forward.</p></div><div><div class="avatars" style="justify-content:flex-end;margin-bottom:12px">${ava('Alex Morgan')}${ava('Taylor Kim')}${ava('Morgan Hayes')}</div>${tag('● On track')}</div></div><div class="sectionhead"><div><h2>Good afternoon, ${state.role==='Client'?'Morgan':state.role==='Contractor'?'Jamie':'Alex'}.</h2><p>${state.role==='Client'?'Two deliverables are ready for your feedback.':'Here’s what’s moving across your project today.'}</p></div><select style="width:155px;font-size:11px" onchange="state.role=this.value;render()">${['Internal team','Client','Contractor'].map(x=>`<option ${state.role===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="role">${state.role} view · ${state.role==='Internal team'?'Full project management access':state.role==='Client'?'Shared milestones, deliverables, and approvals':'Assigned tasks and shared project discussions'} · Role preview</div><div class="two" style="grid-template-columns:1.65fr 1fr"><div>${surface('Work in motion',`<div class="kanban">${['To do','In progress','Complete'].map((s,i)=>`<div class="lane"><h3>${s}<span>${[2,2,2][i]}</span></h3>${[['Validate requirements','Confirm pilot audience'],['Review dashboard','Map reporting sources'],['Approve project scope','Kickoff workshop']][i].map((n,j)=>`<div class="task" onclick="projectTask('${n}')"><span class="tag ${i===2?'green':''}">${['Planning','Delivery','Complete'][i]}</span><p style="margin:11px 0 0"><b>${n}</b></p><div class="row"><span class="subtle">Oct ${22+i+j}</span>${ava(['Alex Morgan','Taylor Kim','Jordan Ellis'][i])}</div></div>`).join('')}</div>`).join('')}</div>`,btn('Full project plan ↗','tab=1;render()','link'))}<div class="two equal" style="margin-top:20px">${surface('Shared files',`<div class="filechip"><span class="fileicon"></span><div><b>Pilot brief.pdf</b><small>Updated today · SharePoint</small></div></div><div class="filechip"><span class="fileicon"></span><div><b>Dashboard preview.pdf</b><small>Ready for client review</small></div></div>${btn('Open file workspace →','tab=2;render()','link')}`)}${surface('Next milestone',`<span class="eyebrow" style="font-size:9px">FRIDAY / OCTOBER 23</span><h2 style="font-size:19px;margin:13px 0">Pilot review</h2><p class="muted">A working walkthrough of the reporting dashboard and feedback from the team.</p>${bar(78)}<div class="metricline" style="font-size:10px"><span>Milestone readiness</span><b>78%</b></div>`)}</div></div>${surface('Project conversation',`<div class="messagefeed"><div class="feedpost">${ava('Taylor Kim')}<div><b>Taylor Kim</b> <small>· 24 minutes ago</small><p>The dashboard preview is ready. I’ve added the exception view we discussed. Please share feedback before Friday.</p>${tag('Dashboard preview.pdf')}</div></div><div class="feedpost">${ava('Alex Morgan')}<div><b>Alex Morgan</b> <small>· 1 hour ago</small><p>Data mapping is complete. We’ll focus the next review on ownership and the handoff workflow.</p></div></div>${state.posts.map(x=>`<div class="feedpost">${ava(state.role==='Client'?'Morgan Hayes':'Alex Morgan')}<div><b>${state.role}</b> <small>· Just now</small><p>${esc(x)}</p></div></div>`).join('')}</div><div class="composer"><input id="post" placeholder="Share an update…" style="font-size:11px" onkeydown="if(event.key==='Enter')post()">${btn('↑','post()','primary')}</div><p class="subtle">Teams-connected workflow · No live notifications in demo</p>`)}</div></div>`}
function insights2(){if(tab===1)return legacy(8);return `<div class="appbody"><div class="dashboardtop"><div><div class="eyebrow">EXECUTIVE PULSE / ${state.reportPeriod.toUpperCase()}</div><h1>The bigger picture. In one place.</h1><p>24 reports connected across six business functions.</p></div><select style="width:145px;font-size:11px" onchange="state.reportPeriod=this.value;render()">${['This quarter','Last quarter'].map(x=>`<option ${state.reportPeriod===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="querybar"><span style="color:var(--gold);font-size:20px"></span><input id="reportQuestion" placeholder="Ask across your reports: What needs our attention this week?">${btn('Ask insights →','askReports()','primary')}</div>${slim([['Revenue',state.reportPeriod==='This quarter'?'$3.84M':'$3.42M','↑ 12.3% vs. prior quarter'],['Delivery confidence','86 / 100','4 milestones completed'],['Budget utilization','72%','Within planned range'],['Team utilization',state.rebalance?'88%':'94%','Target: 80–95%']])}<div class="dashgrid">${surface('Revenue & performance',`<div class="legend"><span><i></i>Revenue</span><span><i style="background:#ccc5ba"></i>Comparison period</span></div>${lineChart(state.reportPeriod==='This quarter'?1.1:.9)}`,btn('Explore ↗','nav(5)','link'),'wide')}${surface('Leadership attention',`<div class="listitem"><div class="row"><b style="font-size:11px">Pipeline concentration</b>${tag('Watch','amber')}</div><p class="muted" style="font-size:10px">Two deals drive 41% of weighted pipeline.</p>${btn('Inspect sales →','nav(5)','link')}</div><div class="listitem"><div class="row"><b style="font-size:11px">Delivery capacity</b>${tag(state.rebalance?'Balanced':'Action',state.rebalance?'green':'red')}</div><p class="muted" style="font-size:10px">${state.rebalance?'The team has been rebalanced.':'Two people exceed weekly capacity.'}</p>${btn('Review team →','nav(6)','link')}</div><div class="listitem"><b style="font-size:11px">Forecast baseline</b><p class="muted" style="font-size:10px">Finance sign-off is still pending.</p></div>`)}${surface('Marketing engagement',`<span class="bigmetric">76% <span style="font-size:11px;color:var(--green);letter-spacing:0">↑ 9 pts</span></span><p class="subtle">Webinar attendance rate</p><div class="microbars">${[30,45,39,56,48,64,58,72,69,84,77,91].map(n=>`<i style="height:${n}%"></i>`).join('')}</div><div class="row subtle" style="margin-top:12px"><span>JAN</span><span>DEC</span></div>`,btn('Open ↗','nav(1)','link'))}${surface('Budget allocation',`<div class="ring" style="width:115px;height:115px;margin:7px auto 17px"><div style="width:91px;height:91px;font-size:24px">72%<small>Utilized</small></div></div>${[['Operations',49],['Marketing',23],['Technology',16],['People',12]].map(([x,n])=>`<div class="row" style="font-size:9px;margin:8px 0"><span>${x}</span><b>${n}%</b></div>`).join('')}`,btn('Open ↗','nav(4)','link'))}${surface('Capacity by discipline',`<div class="heatmap"><span></span>${['W1','W2','W3','W4','W5','W6'].map(x=>`<span>${x}</span>`).join('')}${['Design','Data','Build','QA','Delivery'].map((x,i)=>`<span>${x}</span>${Array.from({length:6},(_,j)=>`<i style="background:${['#e9e4d7','#c5ceb9','#b5c2a6','#b58b60'][(i+j)%4]}"></i>`).join('')}`).join('')}</div><div class="legend" style="margin-top:20px"><span><i style="background:#e9e4d7"></i>Available</span><span><i style="background:#b58b60"></i>At capacity</span></div>`,btn('Open ↗','nav(6)','link'))}${surface('Project health',`${[['On track',4,67],['Needs attention',2,33],['Blocked',0,0]].map(([x,n,p])=>`<div class="metricline" style="font-size:10px"><span>${x}</span><b>${n} projects</b></div>${bar(p,x==='On track')}`).join('')}`,btn('View portfolio ↗','nav(11)','link'))}${surface(' The connection worth noticing',`<h2 style="font-size:18px;line-height:1.45;margin:0 0 12px">Growth and delivery need to be planned together.</h2><p class="muted" style="font-size:11px">If both late-stage opportunities close, the current delivery plan will need more capacity. Align kickoff dates with team availability before committing.</p><div class="suggestions">${tag('Source: Sales performance')}${tag('Source: Team capacity')}</div>${btn('Explore the scenario →','nav(9)','link')}`,'','wide')}</div></div>`}
function askReports(){let q=$('#reportQuestion')?.value||'What needs leadership attention?';draw('Insights across your reports',`<span class="eyebrow">YOUR QUESTION</span><p>${esc(q)}</p><div class="callout"><b>Sample cross-report answer</b><br>Revenue is increasing, but the team has limited spare capacity. Two opportunities represent 41% of weighted pipeline. Align their expected start dates with the resource plan before confirming delivery commitments.</div><h2 style="margin-top:24px">Reports used</h2><div class="filechip"><span class="fileicon"></span><div><b>Sales performance</b><small>Pipeline concentration & expected close dates</small></div></div><div class="filechip"><span class="fileicon"></span><div><b>Team capacity</b><small>Allocation & availability</small></div></div>${btn('Explore team capacity →','closeDrawer();nav(6)','primary')}`)}
function forecastChart(v){let end=170-v*23;return `<svg viewBox="0 0 700 280" class="chart" style="height:310px" role="img" aria-label="Scenario revenue projection compared with baseline"><defs><linearGradient id="farea" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#bf9558" stop-opacity=".18"/><stop offset="1" stop-color="#bf9558" stop-opacity=".02"/></linearGradient></defs>${[40,95,150,205].map((y,i)=>`<line x1="40" y1="${y}" x2="680" y2="${y}" stroke="#ece8df"/><text x="0" y="${y+4}" font-size="10" fill="#938b7d">$${6-i}M</text>`).join('')}<rect x="370" y="15" width="310" height="220" fill="#faf6ed"/><text x="455" y="34" font-size="9" fill="#b39870" letter-spacing="1">FORECAST PERIOD</text><path d="M40 211 L95 188 L150 198 L205 161 L260 167 L315 143 L370 134 L425 ${145-v*5} L480 ${130-v*8} L535 ${115-v*10} L590 ${100-v*12} L650 ${end} L650 235 L40 235Z" fill="url(#farea)"/><path d="M40 211 L95 188 L150 198 L205 161 L260 167 L315 143 L370 134" fill="none" stroke="#a47c41" stroke-width="3"/><path d="M370 134 L425 123 L480 118 L535 107 L590 100 L650 90" fill="none" stroke="#bfb9ad" stroke-width="2" stroke-dasharray="5 5"/><path d="M370 134 L425 ${145-v*5} L480 ${130-v*8} L535 ${115-v*10} L590 ${100-v*12} L650 ${end}" fill="none" stroke="#a47c41" stroke-width="3" stroke-dasharray="6 4"/><line x1="370" y1="45" x2="370" y2="235" stroke="#d1c3ab" stroke-dasharray="3 3"/>${['Jul','Aug','Sep','Oct','Nov','Dec'].map((x,i)=>`<text x="${40+i*122}" y="263" font-size="10" fill="#938b7d">${x}</text>`).join('')}</svg>`}
function forecast2(){let projected=3.84*(1+state.growth/100)*state.win/32;return `<div class="forecastshell"><div class="scenarioControls"><div class="eyebrow" style="font-size:9px">SCENARIO CONTROLS</div><h2 style="font-size:19px;margin:12px 0 8px">Build your outlook.</h2><p class="muted" style="font-size:11px">Adjust the drivers. See the implications immediately.</p><div class="suggestions">${btn('Conservative','state.growth=5;state.win=30;render()')}${btn('Growth','state.growth=20;state.win=38;render()')}</div><div class="sliderbox"><div class="row"><span>Pipeline growth</span><b>${state.growth}%</b></div><input aria-label="Pipeline growth" type="range" min="-10" max="40" value="${state.growth}" oninput="state.growth=+this.value;updateForecast()"><div class="sliderlabels"><span>−10%</span><span>40%</span></div><p style="margin-top:12px">Change in the value of qualified opportunities.</p></div><div class="sliderbox"><div class="row"><span>Win rate</span><b>${state.win}%</b></div><input aria-label="Win rate" type="range" min="15" max="50" value="${state.win}" oninput="state.win=+this.value;updateForecast()"><div class="sliderlabels"><span>15%</span><span>50%</span></div><p style="margin-top:12px">Expected conversion compared with a 32% baseline.</p></div><div class="listitem"><div class="row"><span class="muted" style="font-size:10px">Baseline revenue</span><b>$3.84M</b></div></div><div class="listitem"><div class="row"><span class="muted" style="font-size:10px">Planning horizon</span><b>90 days</b></div></div><div class="callout" style="margin-top:22px"><b>Assumptions are visible.</b><br>This model shows sensitivity to growth and conversion. It is not a prediction.</div>${btn('Reset assumptions','state.growth=12;state.win=32;render()','link')}</div><div class="scenarioCanvas"><div class="sectionhead"><div><h2>Next-quarter revenue outlook</h2><p>Current scenario · Compared with your baseline</p></div>${tag('Unsaved scenario','amber')}</div><div class="forecastcompare"><div><small>BASELINE</small><strong>$3.84M</strong><span class="subtle">Current-quarter reference</span></div><div class="selected"><small>YOUR SCENARIO</small><strong id="forecastValue">$${projected.toFixed(2)}M</strong><span class="subtle" id="forecastDelta">${((projected/3.84-1)*100).toFixed(1)}% vs. baseline</span></div><div><small>ILLUSTRATIVE UPSIDE</small><strong>$5.47M</strong><span class="subtle">20% growth · 38% win rate</span></div></div>${surface('Actuals → scenario projection',`<div class="legend"><span><i></i>Actual revenue</span><span><i></i>Your scenario</span><span><span class="legenddash"></span>Baseline outlook</span></div><div id="forecastChart">${forecastChart(projected)}</div>`)}<div id="forecastExplanation" class="callout" style="margin-top:19px"><b>What changed?</b><br>At ${state.growth}% pipeline growth and a ${state.win}% win rate, the scenario is ${money(Math.abs(projected-3.84)*1e6)} ${projected>=3.84?'above':'below'} baseline.</div>${tab===1?`<div class="card" style="margin-top:20px"><h2>Model assumptions</h2>${table(['Driver','Baseline','Scenario'],[['Quarterly revenue','$3.84M','$'+projected.toFixed(2)+'M'],['Pipeline growth','0%',state.growth+'%'],['Win rate','32%',state.win+'%']])}<p class="subtle">Calculation: baseline × (1 + growth) × (scenario win rate ÷ 32%). Other drivers are held constant.</p></div>`:tab===2?`<div class="card" style="margin-top:20px"><h2>Saved scenarios</h2>${table(['Scenario','Growth','Win rate','Revenue'],[['Conservative','5%','30%','$3.78M'],['Your current model',state.growth+'%',state.win+'%','$'+projected.toFixed(2)+'M'],...(state.savedScenarios||[]).map((s,i)=>['Saved scenario '+(i+1),s.growth+'%',s.win+'%','$'+s.value.toFixed(2)+'M'])])}</div>`:`<div class="two equal" style="margin-top:20px">${surface('Decision to consider','<p class="muted">Higher conversion brings delivery forward. Check team availability before confirming new project start dates.</p>'+btn('Review capacity →','nav(6)','link'))}${surface('Model transparency','<p class="subtle">Baseline × (1 + pipeline growth) × (scenario win rate ÷ baseline win rate). Sample data; actual forecasts require validated source inputs.</p>')}</div>`}</div></div>`}
function updateForecast(){let v=3.84*(1+state.growth/100)*state.win/32;$('#forecastValue').textContent='$'+v.toFixed(2)+'M';$('#forecastDelta').textContent=((v/3.84-1)*100).toFixed(1)+'% vs. baseline';$('#forecastChart').innerHTML=forecastChart(v);$('#forecastExplanation').innerHTML=`<b>What changed?</b><br>At ${state.growth}% pipeline growth and a ${state.win}% win rate, the scenario is ${money(Math.abs(v-3.84)*1e6)} ${v>=3.84?'above':'below'} baseline.`;document.querySelectorAll('.sliderbox .row b')[0].textContent=state.growth+'%';document.querySelectorAll('.sliderbox .row b')[1].textContent=state.win+'%'}
function saveScenario(){state.savedScenarios=state.savedScenarios||[];state.savedScenarios.push({growth:state.growth,win:state.win,value:3.84*(1+state.growth/100)*state.win/32});tab=2;render();toast('Scenario saved for comparison')}
function roiValues(){let gross=state.hours*52*state.rate*state.adoption/100;let net=gross-state.running*12;return {gross,net,year:net-state.build,pct:(net-state.build)/state.build*100,payback:net>0?state.build/net*12:null}}
function roi2(){const r=roiValues();return `<div class="appbody"><div class="sectionhead"><div><div class="eyebrow" style="font-size:9px">PROJECT BUSINESS CASE</div><h2 style="font-size:22px;margin:10px 0 6px">Operations reporting automation</h2><p>Measure the opportunity. Test the assumptions. Decide with clarity.</p></div>${tag(state.roiEvidence?'Evidence reviewed':'Evidence grade C · Estimates',state.roiEvidence?'green':'amber')}</div><div class="roishell"><div class="stack" style="align-content:start">${surface('01 / Define the benefit',`<div class="sliderbox" style="padding-top:0"><div class="row"><span>Hours saved per week</span><b id="hoursLabel">${state.hours} hrs</b></div><input aria-label="Weekly hours saved" type="range" min="5" max="120" value="${state.hours}" oninput="state.hours=+this.value;updateRoi()"><div class="sliderlabels"><span>5 hours</span><span>120 hours</span></div></div><div class="sliderbox"><div class="row"><span>Expected team adoption</span><b id="adoptionLabel">${state.adoption}%</b></div><input aria-label="Expected adoption" type="range" min="10" max="100" value="${state.adoption}" oninput="state.adoption=+this.value;updateRoi()"><div class="sliderlabels"><span>10%</span><span>100%</span></div></div><label class="field" style="margin-top:20px">Loaded hourly cost<input type="number" min="1" value="${state.rate}" onchange="state.rate=Math.max(1,+this.value);render()"></label><p class="subtle">Capacity value = hours saved × 52 weeks × hourly cost × adoption.</p>`)}${surface('02 / Account for the investment',`<div class="two equal"><label class="field">One-time build cost<input type="number" min="1" value="${state.build}" onchange="state.build=Math.max(1,+this.value);render()"></label><label class="field">Monthly running cost<input type="number" min="0" value="${state.running}" onchange="state.running=Math.max(0,+this.value);render()"></label></div><div class="callout"><b>Include the ongoing costs.</b><br>Cloud hosting, model usage, maintenance, and any new subscriptions belong in the running-cost estimate.</div>`)}${tab===1?surface('03 / Validate the evidence',`${[['Time baseline','Workflow owner estimate'],['Hourly cost','Finance estimate'],['Adoption','Pilot assumption']].map(([x,y])=>`<div class="listitem row"><div><b>${x}</b><p>${y}</p></div><input style="width:auto" type="checkbox" aria-label="Validate ${x}"></div>`).join('')}${btn('Mark evidence reviewed','state.roiEvidence=true;render()','primary')}`):''}</div><div class="stack" style="align-content:start"><section class="roiresult"><div class="row" style="border:0;padding:0;margin:0"><label>YEAR-ONE NET VALUE</label>${tag('After all modeled costs')}</div><h1 id="roiNet">${money(r.year)}</h1><p style="font-size:11px;color:#655545">The estimated value after implementation and annual running costs.</p><div class="row"><div><label>YEAR-ONE ROI</label><p><b id="roiPct">${r.pct.toFixed(0)}%</b></p></div><div><label>PAYBACK PERIOD</label><p><b id="roiPayback">${r.payback?r.payback.toFixed(1)+' months':'No payback'}</b></p></div></div></section>${surface('How the value adds up',`<div class="waterfall"><div style="height:92%"><span>Benefit</span></div><div style="height:24%;align-self:center"><span>Running</span></div><div style="height:38%;align-self:center"><span>Build</span></div><div style="height:61%"><span>Net value</span></div></div><div class="metricline"><span>Annual gross benefit</span><b id="roiGross">${money(r.gross)}</b></div><div class="metricline"><span>Annual running cost</span><b>−${money(state.running*12)}</b></div><div class="metricline"><span>One-time build</span><b>−${money(state.build)}</b></div><div class="metricline" style="padding-top:15px;border-top:1px solid var(--line)"><span>Year-one net</span><b id="roiNet2">${money(r.year)}</b></div>`)}<div class="callout" id="roiNote"><b>${r.year>0?'A positive case under these assumptions.':'The first-year case needs more work.'}</b><br>Time saved represents capacity value, not guaranteed cash savings. Validate the baseline and adoption through a pilot.</div></div></div>${tab===2?`<div class="card" style="margin-top:22px"><h2>How adoption changes the business case</h2>${table(['Adoption','Realized benefit','Year-one net','ROI'],[25,50,75,100].map(a=>{let g=state.hours*52*state.rate*a/100;let y=g-state.running*12-state.build;return [a+'%',money(g),money(y),(y/state.build*100).toFixed(0)+'%']}))}</div>`:''}</div>`}
function updateRoi(){let r=roiValues();$('#hoursLabel').textContent=state.hours+' hrs';$('#adoptionLabel').textContent=state.adoption+'%';$('#roiNet').textContent=money(r.year);$('#roiNet2').textContent=money(r.year);$('#roiGross').textContent=money(r.gross);$('#roiPct').textContent=r.pct.toFixed(0)+'%';$('#roiPayback').textContent=r.payback?r.payback.toFixed(1)+' months':'No payback';$('#roiNote').innerHTML=`<b>${r.year>0?'A positive case under these assumptions.':'The first-year case needs more work.'}</b><br>Time saved represents capacity value, not guaranteed cash savings. Validate the baseline and adoption through a pilot.`}
function exportRoi2(){let r=roiValues();download('Nine-67-business-case.txt',`Nine-67 / Operations reporting automation\nIllustrative business case\n\nHours saved per week: ${state.hours}\nAdoption: ${state.adoption}%\nLoaded hourly cost: ${money(state.rate)}\nAnnual gross benefit: ${money(r.gross)}\nAnnual running cost: ${money(state.running*12)}\nBuild cost: ${money(state.build)}\nYear-one net: ${money(r.year)}\nROI: ${r.pct.toFixed(1)}%\n\nCapacity value is not guaranteed cash savings.`)}
function tracker2(){if(tab===2)return legacy(11);return `<div class="appbody"><div class="dashboardtop"><div><div class="eyebrow">YOUR NINE-67 DELIVERY PORTFOLIO</div><h1>From possibility to progress.</h1><p>Every build, milestone, and decision in one shared view.</p></div>${tag('6 active initiatives','green')}</div>${slim([['Active initiatives','6','Across your business'],['On track','4','Next steps confirmed'],['Needs attention','2','Decisions to unlock progress'],['Milestones complete','18','Across the program']])}${tab===0?`<div class="portfolioGrid">${projects.map((n,i)=>`<button class="projectcard" onclick="projectDetail(${i})"><div class="row"><div class="projecticon">${['','','','','','↗'][i]}</div>${tag([1,4].includes(i)?'Needs attention':'On track',[1,4].includes(i)?'amber':'green')}</div><h2>${n}</h2><p>${['A shared view of reporting, exceptions, and ownership.','Connect commercial signals with actionable account insight.','Balance team availability with delivery commitments.','One home for project conversations, files, and decisions.','Turn financial assumptions into planning scenarios.','Make every post-webinar conversation more relevant.'][i]}</p><div class="row">${tag(['Pilot','Discovery','Build','Live','Design','Build'][i])}<div class="avatars">${ava('Alex Morgan')}${ava(['Taylor Kim','Jordan Ellis','Sam Rivera'][i%3])}</div></div><div class="metricline"><span>Overall progress</span><b>${[78,18,54,100,32,65][i]}%</b></div>${bar([78,18,54,100,32,65][i],i===3)}<div class="bottom"><span>${['Pilot review · Oct 23','Data access · Oct 21','Team test · Oct 28','Monthly review · Oct 30','Baseline approval · Oct 22','Campaign test · Oct 26'][i]}</span><span>↗</span></div></button>`).join('')}</div>`:`<div class="roadmap"><div class="roadrow" style="font-size:9px;color:var(--muted)"><b>PROJECT / NEXT MILESTONE</b><div class="row"><span>OCT 19</span><span>OCT 26</span><span>NOV 2</span><span>NOV 9</span></div></div>${projects.map((n,i)=>`<div class="roadrow"><div><b>${n}</b><p class="subtle">${['Pilot review','Data access','Team test','Monthly review','Baseline sign-off','Campaign test'][i]}</p></div><div class="roadtrack"><i onclick="projectDetail(${i})" style="left:${[0,7,18,0,30,12][i]}%;width:${[42,30,60,95,45,68][i]}%;background:${i===3?'#c7d4bf':'#ded0b8'}">${['Pilot & refinement','Discovery','Build & test','Live support','Design & model','Build & validation'][i]}</i></div></div>`).join('')}</div>`}<div class="two" style="margin-top:22px">${surface('This week’s decisions',`<div class="listitem row"><div><b>Approve CRM data access</b><p class="muted" style="font-size:10px">Sales intelligence · IT owner</p></div>${btn('Review →','projectDetail(1)','link')}</div><div class="listitem row"><div><b>Confirm the forecast baseline</b><p class="muted" style="font-size:10px">Financial forecasting · Finance owner</p></div>${btn('Review →','projectDetail(4)','link')}</div>`)}${surface(' Portfolio perspective',`<p class="muted">Operations reporting is ready for its first team review. Resolve sales data access this week to protect the next build milestone.</p>${btn('Open the project briefing →','portfolioBrief()','link')}`)}</div></div>`}
function portfolioBrief(){draw('Your portfolio briefing',`<div class="eyebrow">THIS WEEK / DELIVERY</div><h2 style="margin-top:20px">Good momentum. Two decisions matter.</h2><div class="callout"><b>1. Validate the reporting pilot.</b><br>The first iteration is ready for team feedback.</div><div class="listitem"><b>2. Unlock sales data access.</b><p>The discovery phase depends on approval from the data owner.</p></div><div class="listitem"><b>3. Confirm finance assumptions.</b><p>The forecast model needs an agreed baseline before scenario review.</p></div>${btn('Open decisions & risks','closeDrawer();tab=2;render()','primary')}`)}
function nightwatch2(){if(tab===2)return legacy(12);if(tab===1){let old=tab;tab=0;let h=originalViews[12]();tab=old;h=h.replaceAll('tab=1;render()', 'tab=0;render()');return `<div class="appbody">${h}</div>`}let c=companies[state.company];return `<div class="nightlayout"><div class="nightlist"><div class="sectionhead"><h2>Companies</h2>${tag('24')}</div><input placeholder="Find a company…" aria-label="Search companies" style="font-size:10px;margin-bottom:10px" oninput="document.querySelectorAll('[data-company]').forEach(x=>x.style.display=x.dataset.company.includes(this.value.toLowerCase())?'block':'none')">${companies.map((x,i)=>`<button class="companybutton ${state.company===i?'selected':''}" data-company="${x.toLowerCase()}" onclick="state.company=${i};render()"><b>${x}</b><p>${['Manufacturing · PA','Professional services · NJ','Distribution · NY','Engineering · PA'][i]}</p><div class="row">${tag('Fit '+[94,89,86,82][i],state.company===i?'':'green')}<span style="font-size:9px">${['New signal','3 drafts','3 drafts','New signal'][i]}</span></div></button>`).join('')}<div class="callout" style="margin-top:25px;font-size:10px"><b>Nightly research</b><br>50 researched · 24 qualified<br>Last sample run: 2:00 AM</div></div><section class="researchpane"><div class="row"><div class="profilelogo">${c.split(' ').map(x=>x[0]).join('')}</div>${tag('New signal','green')}</div><h1>${c}</h1><p class="muted" style="font-size:10px">${['Manufacturing','Professional services','Distribution','Engineering'][state.company]} · United States</p><div class="card"><div class="row"><div><span class="subtle">ILLUSTRATIVE REVENUE</span><h2 style="font-size:25px;margin:8px 0">${['$84M','$120M','$62M','$48M'][state.company]}</h2></div><span class="subtle">${[210,280,165,140][state.company]} employees</span></div><div class="metricline" style="font-size:10px"><b>AI workflow fit</b><b>${[94,89,86,82][state.company]} / 100</b></div>${bar([94,89,86,82][state.company],true)}</div><div class="eyebrow" style="font-size:9px;margin:24px 0 12px">THE SIGNAL</div><h3 style="font-size:14px;line-height:1.5">${['A new facility. More moving parts.','Leadership hiring signals a new phase.','A systems transition creates an opening.','A growing backlog needs clearer capacity.'][state.company]}</h3><p class="muted" style="font-size:11px">${['Expansion can add handoffs across locations. A shared view of exceptions and ownership could reduce the effort spent chasing updates.','A growing operations team may benefit from a common reporting workflow and more consistent information.','An ERP modernization can expose gaps in how teams move information between systems.','Project growth can make it harder to see who is available and where delivery risk is building.'][state.company]}</p><div class="card"><span class="eyebrow" style="font-size:8px">THE CONVERSATION TO START</span><p style="font-size:12px">${['Bring plant reports, exceptions, and owners into one view.','Make operational reporting consistent across teams.','Simplify the handoff between orders, operations, and service.','Connect project demand with team capacity.'][state.company]}</p></div>${btn('View research & source checklist ↗',"draw('Research evidence','<div class=callout>All companies, metrics, and signals in this workspace are illustrative demonstration data.</div><h2 style=margin-top:24px>Production research checklist</h2><p>Company size and location<br>Source URL and publication date<br>Relevant business signal<br>Contact confidence<br>Suppression and existing-client checks</p>')",'link')}<div class="filechip" style="margin-top:22px"><span class="avatar">${people[state.company][0].split(' ').map(x=>x[0]).join('')}</span><div><b>${people[state.company][0]}</b><small>${people[state.company][1]} · Sample contact</small></div></div></section><section class="draftpane"><div class="sectionhead"><div><h2>Outreach studio</h2><p>One relevant idea. Three ways to start.</p></div>${tag('Draft','amber')}</div><div class="tabs" style="margin:0 0 10px">${['Email','LinkedIn'].map(x=>btn(x,`state.channel='${x}';render()`,state.channel===x?'active':'')).join('')}</div><div class="variantgrid">${versions.map((x,i)=>btn(`${x}<small>${['Offer a specific starting point','Start with a conversation','Show how we deliver'][i]}</small>`,`saveOutreach2();state.variant=${i};render()`,state.variant===i?'selected':'')).join('')}</div><div class="row" style="padding:12px 0 18px"><span class="subtle">${state.channel==='Email'?'TO: '+people[state.company][0].toUpperCase():'LINKEDIN MESSAGE / POST DRAFT'}</span><span class="subtle">Human review required</span></div><label class="field">${state.channel==='Email'?'Subject':'Opening line'}<input id="outSubject" value="${esc(state.drafts['subject'+state.company+state.channel+state.variant]||'One workflow idea for '+c)}" oninput="state.drafts['subject'+state.company+state.channel+state.variant]=this.value"></label><textarea id="outreach" oninput="saveOutreach2();document.getElementById('draftCount').textContent=this.value.length+' characters'">${esc(outreachText())}</textarea><div class="draftbottom"><span id="draftCount">${outreachText().length} characters</span><span>Autosaved in this session</span></div><div class="row" style="margin-top:24px">${btn('Copy draft','copyOutreach()')}${btn(state.drafts['ready'+state.company+state.channel+state.variant]?'Ready ✓':'Mark ready for review',"saveOutreach2();state.drafts['ready'+state.company+state.channel+state.variant]=true;render();toast('Draft marked ready. No outreach sent.')",'primary')}</div><div class="callout" style="margin-top:25px"><b>Why this angle?</b><br>${['A concrete workflow makes the idea easier to understand and respond to.','A simple invitation lets the prospect describe the problem in their own words.','A focused first iteration makes the delivery approach tangible.'][state.variant]}</div></section></div>`}
function saveOutreach2(){if($('#outreach'))state.drafts['out'+state.company+state.channel+state.variant]=$('#outreach').value}
async function copyOutreach(){saveOutreach2();let t=$('#outreach').value;try{await navigator.clipboard.writeText(t);toast('Draft copied')}catch{download('Nine-67-outreach.txt',t);toast('Draft downloaded')}}
// Keep original detail workflows, with richer source-specific data in the main applications.
const oldProjectDetail=projectDetail;projectDetail=function(i){oldProjectDetail(i);let el=$('#drawer');el.innerHTML+=`<div class="card" style="margin-top:20px"><h2>Delivery evidence</h2><div class="listitem"><b>Last demonstration</b><p>Working review completed with the project team.</p></div><div class="listitem"><b>Success measure</b><p>Time spent on the workflow, data completeness, and team adoption.</p></div><div class="listitem"><b>Next decision</b><p>${['Confirm pilot participants','Approve source data access','Confirm team assignments','Review adoption feedback','Approve baseline assumptions','Approve campaign content'][i]}</p></div></div>`};

